def main():
    os.makedirs(OUT, exist_ok=True)
    ids = ["BZ-029","BZ-030","BZ-031","BZ-032","BZ-033","BZ-034","BZ-035","BZ-036","BZ-037","BZ-038",
           "BZ-039","BZ-040","BZ-041","BZ-042","BZ-104","BZ-105","BZ-301","BZ-302","BZ-303","BZ-304"]
    written = []
    for cid in ids:
        d = DATA[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": dict(TRIG)}
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        written.append(path)
    # 自验：逐件精确回读
    ok = 0
    for cid in ids:
        path = os.path.join(OUT, cid + ".json")
        with open(path, encoding="utf-8") as f:
            r = json.load(f)
        assert r["case_id"] == cid
        assert set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
        t = r["trigger"]
        assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, (cid, t)
        assert isinstance(r["confidence"], (int, float)) and 0 <= r["confidence"] <= 1
        assert r["prediction_text"] and r["basis"]
        ok += 1
    print("written:", len(written), "verified:", ok)

if __name__ == "__main__":
    main()
